from .analyzer import Analyzer, PatternSet


def _markdown(report: dict) -> str:
    lines = ["# Workflow Analytics Report", "", "## Read This First", ""]
    for item in report["periods"]["last-2-weeks"]["read_this_first"]: lines.append(f"- {item}")
    lines += ["", "## Inventory", "", f"- Sessions: {report['inventory']['sessions']}", f"- Parse fragments: {len(report['parse_health'])}", "", "## Last 2 Weeks Scorecard", "", "| Row | Observation |", "|---|---|"]
    for row in report["periods"]["last-2-weeks"]["scorecard"]:
        lines.append(f"| {row['row']} {row['name']} | `{json.dumps({k:v for k,v in row.items() if k not in ('row','name')}, ensure_ascii=False)}` |")
    lines += ["", "Trace-derived process metrics only. Raw prompts and full logs are intentionally excluded."]
    return "\n".join(lines) + "\n"


def _load(args: argparse.Namespace) -> tuple[Analyzer, list[dict]]:
    patterns = PatternSet.from_file(args.patterns) if getattr(args, "patterns", None) else None
    analyzer = Analyzer(args.sessions_root, patterns, getattr(args, "active_session", None))
    return analyzer, analyzer.sessions(include_active=getattr(args, "include_active", False))


def cmd_analyze(args: argparse.Namespace) -> int:
    analyzer, sessions = _load(args)
    report = analyzer.report(sessions)
    destination = Path(args.output).expanduser().resolve()
    if destination.is_relative_to(analyzer.root):
        raise SystemExit("Refusing output inside sessions root; choose an explicit derived-artifact destination outside it.")
    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.write_text(_markdown(report) if args.format == "markdown" else json.dumps(report, indent=2, ensure_ascii=False, default=str), encoding="utf-8")
    print(f"Wrote {args.format} report to {destination}; analyzed {len(sessions)} merged sessions read-only.")
    return 0


