def cmd_serve(args: argparse.Namespace) -> int:
    analyzer, sessions = _load(args)
    # Aggregate summaries stay stable by excluding the currently running task,
    # while the selected-chat dashboard can still inspect it explicitly.
    inspectable_sessions = analyzer.sessions(include_active=True)
    by_id = {s["id"]: s for s in inspectable_sessions}
    projects = defaultdict_list(inspectable_sessions)
    remote = args.host not in {"127.0.0.1", "localhost", "::1"}
    if remote and not (args.username and args.password): raise SystemExit("Remote binding requires --username and --password (use TLS termination in front of Basic Auth).")
    expected = "Basic " + base64.b64encode(f"{args.username}:{args.password}".encode()).decode() if remote else None
    class Handler(BaseHTTPRequestHandler):
        def _authorized(self):
            if not expected or self.headers.get("Authorization") == expected: return True
            self.send_response(401); self.send_header("WWW-Authenticate", 'Basic realm="workflow-analytics"'); self.end_headers(); return False
        def do_GET(self):
            if not self._authorized(): return
            parsed, q = urlparse(self.path), parse_qs(urlparse(self.path).query)
            if parsed.path == "/health": return self._json({"status": "ok", "read_only": True})
            if parsed.path == "/api/projects": return self._json(projects)
            if parsed.path == "/api/period": return self._json(analyzer.period(sessions, q.get("name", ["this-week"])[0]))
            if parsed.path == "/api/compare": return self._json(analyzer.comparison(sessions))
            if parsed.path == "/api/session":
                item = by_id.get(q.get("id", [""])[0])
                if not item: self.send_error(404, "Session not found"); return
                response = {"id": item["id"], "title": item["title"], "workflow_card": analyzer.workflow_card(item), "summary": item["summary"], "context_progress": analyzer.context_progress(item)}
                injected_prefixes = ("<recommended_plugins>", "<environment_context>", "<app-context>", "<skills_instructions>")
                response["trace_ledger"] = [
                    {key: event[key] for key in ("id", "time", "kind", "actor", "title", "context", "tool", "score", "linked_output_ids", "linked_call_id") if key in event}
                    for event in item["events"]
                    if event["kind"] != "lifecycle"
                    and event["kind"] != "token_count"
                    and (event["actor"] != "system" or event["kind"] in {"compaction", "completion"})
                    and not event["context"].lstrip().startswith(injected_prefixes)
                ]
                if q.get("detail") == ["1"]:  # explicit raw-trace audit request only
                    response["events"] = item["events"]
                return self._json(response)
            if parsed.path == "/": self.send_response(200); self.send_header("Content-Type", "text/html; charset=utf-8"); self.end_headers(); self.wfile.write(_page().encode()); return
            self.send_error(404)
        def _json(self, value): self.send_response(200); self.send_header("Content-Type", "application/json"); self.end_headers(); self.wfile.write(json.dumps(value, default=str).encode())
        def log_message(self, fmt, *values): pass
    server = ThreadingHTTPServer((args.host, args.port), Handler)
    print(f"Serving read-only dashboard at http://{args.host}:{args.port} ({len(sessions)} aggregate, {len(inspectable_sessions)} selectable sessions). Ctrl-C to stop.")
    try: server.serve_forever()
    except KeyboardInterrupt: pass
    finally: server.server_close()
    return 0


def defaultdict_list(sessions):
    groups = {}
    for session in sessions: groups.setdefault(session["project"], []).append({"id": session["id"], "title": session["title"]})
    return [{"project": project, "sessions": rows} for project, rows in sorted(groups.items())]


def parser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(description="Read-only Codex session workflow analytics")
    sub = p.add_subparsers(required=True)
    for name, handler in (("analyze", cmd_analyze), ("serve", cmd_serve)):
        cmd = sub.add_parser(name); cmd.add_argument("--sessions-root", required=True); cmd.add_argument("--patterns"); cmd.add_argument("--active-session"); cmd.add_argument("--include-active", action="store_true"); cmd.set_defaults(func=handler)
        if name == "analyze": cmd.add_argument("--output", required=True); cmd.add_argument("--format", choices=("json", "markdown"), default="json")
        else: cmd.add_argument("--host", default="127.0.0.1"); cmd.add_argument("--port", type=int, default=8765); cmd.add_argument("--username"); cmd.add_argument("--password")
    return p


def main() -> int:
    args = parser().parse_args()
    return args.func(args)

if __name__ == "__main__": raise SystemExit(main())
